(()=>{function mount(){const head=document.querySelector(".workspace>.page-head");if(!head)return;let card=document.getElementById("tvu-productivity-entry");if(!card){card=document.createElement("section");card.id="tvu-productivity-entry";head.after(card)}if(card.dataset.graphVersion==="2")return;card.dataset.graphVersion="2";card.innerHTML="<section id=\"recycling-top5\" style=\"background:white;padding:24px;border:1px solid #e2d7eb;border-radius:18px;margin:24px 0;color:#342742\"><small>2025 생산성 평가 · 환경 세부지표</small><h2 style=\"margin:8px 0\">생활계폐기물 재활용률 상위 5개 지역</h2><p>관할 기초지자체의 재활용률을 광역별로 평균한 수치입니다. 생산성 종합점수 순위가 아닙니다.</p><div style=\"max-width:900px\"><div style=\"display:grid;grid-template-columns:65px 1fr 85px;gap:12px;align-items:center;margin:18px 0\"><strong>1 광주</strong><div style=\"height:28px;border-radius:7px;background:#f2edf8\"><div style=\"height:100%;width:91.04%;border-radius:7px;background:#7950a7\"></div></div><strong style=\"font-size:21px;text-align:right\">91.04%</strong></div><div style=\"display:grid;grid-template-columns:65px 1fr 85px;gap:12px;align-items:center;margin:18px 0\"><strong>2 부산</strong><div style=\"height:28px;border-radius:7px;background:#f2edf8\"><div style=\"height:100%;width:80.72%;border-radius:7px;background:#b59ace\"></div></div><strong style=\"font-size:21px;text-align:right\">80.72%</strong></div><div style=\"display:grid;grid-template-columns:65px 1fr 85px;gap:12px;align-items:center;margin:18px 0\"><strong>3 대전</strong><div style=\"height:28px;border-radius:7px;background:#f2edf8\"><div style=\"height:100%;width:65.88%;border-radius:7px;background:#b59ace\"></div></div><strong style=\"font-size:21px;text-align:right\">65.88%</strong></div><div style=\"display:grid;grid-template-columns:65px 1fr 85px;gap:12px;align-items:center;margin:18px 0\"><strong>4 서울</strong><div style=\"height:28px;border-radius:7px;background:#f2edf8\"><div style=\"height:100%;width:60.97%;border-radius:7px;background:#b59ace\"></div></div><strong style=\"font-size:21px;text-align:right\">60.97%</strong></div><div style=\"display:grid;grid-template-columns:65px 1fr 85px;gap:12px;align-items:center;margin:18px 0\"><strong>5 인천</strong><div style=\"height:28px;border-radius:7px;background:#f2edf8\"><div style=\"height:100%;width:59.79%;border-radius:7px;background:#b59ace\"></div></div><strong style=\"font-size:21px;text-align:right\">59.79%</strong></div></div><p style=\"font-size:13px;color:#73647e\">보고서 전국 평균 53.49% · 막대 길이 0~100% 기준<br>출처: 한국생산성본부, 2025년 지방자치단체 생산성지수 측정 최종보고서, 본문 75쪽(첨부 PDF 42쪽), 그림 Ⅱ-46.</p></section>";const a=document.createElement("a");a.href="/productivity-2025.html";a.textContent="생산성 평가 자료와 수상기관 전체 보기 →";card.append(a)}new MutationObserver(mount).observe(document.body,{childList:true,subtree:true});mount()})();